const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const volcano = ee.Geometry.Point([29.204, -1.408]); // Nyamulagira
  const roi = volcano.buffer(50000); // 50 km buffer

  const date = '2025-02-20';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // Helper function to get Landsat 8 SR image
  function getL8Image(start, end) {
    return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(start, end)
      .sort('CLOUD_COVER')
      .first();
  }

  // Try to get image for the exact date
  let image = getL8Image(startDate, endDate);

  // If no image, try Landsat 9
  if (image.getInfo() === null) {
    image = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .sort('CLOUD_COVER')
      .first();
  }

  // If still no image, widen the date range to ±3 days
  if (image.getInfo() === null) {
    const widerStart = startDate.advance(-3, 'day');
    const widerEnd = endDate.advance(3, 'day');
    image = getL8Image(widerStart, widerEnd);
    if (image.getInfo() === null) {
      image = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(roi)
        .filterDate(widerStart, widerEnd)
        .sort('CLOUD_COVER')
        .first();
    }
  }

  // Check if we have an image
  if (image.getInfo() === null) {
    print("No images found for the specified date and location.");
    print("<answer>C1</answer>");
    return;
  }

  // 2. Data Preprocessing & Cloud Masking
  // Apply scale factors to reflectance bands
  function applyScaleFactors(img) {
    const opticalBands = img.select('SR_B.').multiply(0.0000275).add(-0.2);
    const thermalBands = img.select('ST_B.*').multiply(0.00341802).add(149.0);
    return img.addBands(opticalBands, null, true)
              .addBands(thermalBands, null, true);
  }

  image = applyScaleFactors(image);

  // Cloud masking using QA_PIXEL
  const qa = image.select('QA_PIXEL');
  const cloudMask = qa.bitwiseAnd(1 << 3).eq(0); // Clear cloud bit (bit 3)
  const shadowMask = qa.bitwiseAnd(1 << 4).eq(0); // Clear cloud shadow bit (bit 4)
  const mask = cloudMask.and(shadowMask);
  image = image.updateMask(mask);

  // 3. Plume Detection
  // Use visible and SWIR bands for plume detection
  const b2 = image.select('SR_B2'); // Blue
  const b3 = image.select('SR_B3'); // Green
  const b6 = image.select('SR_B6'); // SWIR1

  // Simple plume mask: high visible reflectance and low SWIR
  const plumeMask = b2.add(b3).divide(2).gt(0.25).and(b6.lt(0.15));
  const plumeImage = image.updateMask(plumeMask);

  // Count plume pixels
  const plumeCount = plumeMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9,
  }).get('SR_B2');

  const count = plumeCount.getInfo();
  print(`Plume pixel count: ${count}`);

  if (count === 0) {
    print("No valid plume pixels after masking.");
    print("<answer>C2</answer>");
    return;
  }

  // 4. Compute Mean Longitude of Plume Pixels
  // Create an image with longitude values
  const lonImg = ee.Image.pixelLonLat().select('longitude');
  // Mask by plume mask and compute mean longitude
  const meanLon = lonImg.updateMask(plumeMask).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9,
  }).get('longitude');

  const meanLonVal = meanLon.getInfo();
  print(`Mean plume longitude: ${meanLonVal}`);
  print(`Volcano longitude: 29.204`);

  // 5. Validation & Final Answer
  if (meanLonVal === null || meanLonVal === undefined || isNaN(meanLonVal)) {
    print("<answer>C3</answer>");
  } else if (meanLonVal > 29.204) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
